from pathlib import Path
import json,re,html
SITE=Path(__file__).resolve().parents[1]
h=lambda x:html.escape(str(x),quote=True)
data=json.loads((SITE/'scripts/course-catalog.json').read_text())
meta=data['courses']; legacy=data['orientations']
base=(SITE/'college-by-design.html').read_text();nav=re.search(r'<nav\b.*?</nav>',base,re.S).group();footer=re.search(r'<footer>.*?</footer>',base,re.S).group()
if '/courses.html' not in nav:
 nav=nav.replace('<a href="/products.html">Products</a>','<a href="/products.html">Products</a><a href="/courses.html">Learning</a>')
if '/courses.html' not in footer:
 footer=footer.replace('<h4>Resources</h4>','<h4>Resources</h4><a href="/courses.html">Courses &amp; learning</a>')
transcript=data['welcome']['transcript']

def welcome():return f'''<section class="cl-welcome" aria-labelledby="welcome-title"><div><p class="cl-label">Meet your guide</p><h2 id="welcome-title">A welcome from Brian.</h2><p>Brian Kennedy Jr., M.Ed., introduces The Ballers Kingdom through his authorized AI avatar. This is a shared welcome, separate from course-specific instruction.</p><details><summary>Read the exact welcome transcript</summary><p>{h(transcript)}</p></details></div><div class="cl-video" data-video-id="r1qIDsBBbqw" data-media-url="{h(data["welcome"]["mediaUrl"])}"><div class="cl-video-placeholder"><span class="cl-play" aria-hidden="true">▶</span><h3>Let’s get to work.</h3><p>Loading the player connects to our video host. Playback starts only when you press play.</p><button type="button" class="btn btn-primary" data-load-video>Load Brian’s welcome</button><a href="{h(data["welcome"]["mediaUrl"])}" target="_blank" rel="noopener noreferrer">Open Brian’s welcome video <span class="sr-only">(opens in a new tab)</span></a></div></div><noscript><p><a href="{h(data["welcome"]["mediaUrl"])}">Open Brian’s welcome video</a> or read the transcript above.</p></noscript></section>'''

def specific_intro(intro,title):
 seconds=round(intro.get('durationSeconds',0))
 return f'''<section class="cl-welcome" aria-labelledby="course-intro-title"><div><p class="cl-label">Start with Brian</p><h2 id="course-intro-title">{h(title)}: your first step.</h2><p>Brian introduces this resource through his authorized AI avatar and approved natural voice. This {seconds}-second introduction gives you a specific first action.</p><details><summary>Read the exact introduction transcript</summary><p>{h(intro['transcript'])}</p></details></div><div class="cl-video" data-media-url="{h(intro['mediaUrl'])}"><div class="cl-video-placeholder"><h3>Put your learning to work.</h3><p>Loading connects to our video host. Press play when you are ready.</p><button type="button" class="btn btn-primary" data-load-video>Load the course introduction</button><a href="{h(intro['mediaUrl'])}" target="_blank" rel="noopener noreferrer">Open the introduction video</a></div></div></section>'''

def page(title,desc,body,path):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{h(title)} | The Ballers Kingdom</title><meta name="description" content="{h(desc)}"><link rel="canonical" href="https://ballkingdom.com/{path.removesuffix('.html')}"><link rel="icon" href="/assets/img/favicon.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@400;500;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/css/styles.css"><link rel="stylesheet" href="/assets/css/course-library.css"></head><body><a class="cl-skip" href="#main-content">Skip to learning content</a>{nav}<main id="main-content" class="cl-main">{body}</main>{footer}<script src="/assets/js/main.js"></script><script src="/assets/js/course-library.js" defer></script></body></html>'''

def card(c):
 n=len(c['lessons'])
 return f'''<article class="cl-card"><p class="cl-label">{n} lessons · Written self-guided edition</p><h3><a href="/courses/{h(c['id'])}.html">{h(c['title'])}</a></h3><p>{h(c['summary'])}</p><p class="cl-audience">For {h(', '.join(c['audiences']))}</p><a class="cl-link" href="/courses/{h(c['id'])}.html">Explore this course</a></article>'''

catalog_public=[]
for c in meta:
 d=c;n=len(c['lessons']);price=c['availability'].get('priceUsd');state=c['availability']
 pricecopy=('$'+str(price)+(' USD. ' if state['status']=='published' else ' planned launch price. ') if price and c['id']!='education-by-design' else '')+state['priceStatus']
 cta=f'<a class="btn btn-primary" data-course-purchase href="{h(state["url"])}"'+(' target="_blank" rel="noopener noreferrer"' if state['url'] and state['url'].startswith('https') else '')+f'>{h(state["label"])}</a>' if state['url'] else '<p class="cl-release-status" data-course-purchase>Release being prepared</p>'
 lessonlist=''.join(f'<li><div><h3>{h(l["title"])}</h3><p>Build: {h(l["artifact"])}</p></div></li>' for l in d['lessons'])
 # Only a small original practice excerpt is public, never the full lesson teaching or paid demo transcript.
 sample=c['sample']; fields=sample['templateFields']
 body=f'''<header class="cl-hero cl-course-hero"><div class="container"><a class="cl-back" href="/courses.html">All learning paths</a><div class="cl-course-intro"><div><p class="cl-label">{n} lessons · Self-guided written course</p><h1>{h(c['title'])}</h1><p class="lead">{h(c['summary'])}</p><p>By Brian Kennedy Jr., M.Ed.</p><div class="cl-availability" data-course-id="{h(c['id'])}" data-course-availability="{h(state['status'])}">{cta}<p>{h(pricecopy)}</p></div></div><aside class="cl-course-facts"><h2>Your working format</h2><p>Written lessons, fictional worked examples, practice templates, checks with explanations, and a final project.</p><p>Estimated working time: {c['estimatedMinutes']} minutes, including exercises. Work at your own pace.</p><p>Course-specific videos are not included in this edition. The shared Brian avatar welcome is available below.</p></aside></div></div></header><div class="container cl-content"><section class="cl-section"><h2>Who this is for</h2><ul class="cl-tags">{''.join('<li>'+h(a)+'</li>' for a in c['audiences'])}</ul></section><section class="cl-section cl-two-column"><div><h2>What you will build</h2><p>{h(c['outcomes'][0])}</p><p>No paid software, public posting, real outreach or sale is required. Use a private real situation or a clearly labeled fictional case.</p></div><div><h2>How you will know you learned</h2><p>Complete an observable piece of work, check your reasoning, and revise it using an original instructional rubric. Return to a new case after 14 days.</p><p>This is educational practice. No accredited certification or admissions, employment, income or wealth result is promised.</p></div></section><section class="cl-section"><h2>The learning sequence</h2><ol class="cl-lesson-list">{lessonlist}</ol></section><section class="cl-sample" aria-labelledby="sample-title"><p class="cl-label">A free practice sample</p><h2 id="sample-title">Start with a decision you can name.</h2><p>Try these first three prompts from “{h(sample['title'])}.” Use a notebook or your preferred accessible format. Your answers stay with you; this page collects no worksheet responses.</p><ol>{''.join('<li>'+h(f)+'</li>' for f in fields)}</ol><details><summary>Check your reasoning</summary><p>{h(sample['check']['question'])}</p><p>{h(sample['check']['answer'])}</p></details></section>{welcome()}<section class="cl-section cl-next"><h2>Choose your next step.</h2><p>Explore the resource that fits your current decision, or ask about facilitated learning for a group.</p><div class="cl-actions"><a class="btn btn-outline" href="/courses.html">Browse learning paths</a><a class="btn btn-outline" href="/contact.html">Ask about group learning</a></div></section></div>'''
 if c['id'] in data.get('courseIntros',{}):
  body=body.replace(welcome(),specific_intro(data['courseIntros'][c['id']],c['title']))
  delivery='A course-specific introduction with English captions is available below. The course video update includes '+str(c['videoEdition']['lessonVideoCount'])+' narrated worked examples, descriptive transcripts, written lessons and reviewed practice.'
  if c['availability']['status']!='published':delivery+=' Group delivery and institutional use are scoped separately.'
  body=body.replace('Course-specific videos are not included in this edition. The shared Brian avatar welcome is available below.',delivery)
 (SITE/'courses'/(c['id']+'.html')).write_text(page(c['title'],c['summary'],body,'courses/'+c['id']+'.html'))

orientations=[]
for x in legacy:
 id=x['id'];p=x if x.get('resourceUrl') else None;path=x['path']; title=x['title']
 if p: action=f'<a class="btn btn-primary" href="{h(p["resourceUrl"])}" target="_blank" rel="noopener noreferrer">View the workbook on Gumroad</a><p>${p["priceCents"]/100:g} USD · Current checkout details are provided by Gumroad.</p>';description=x['description']
 elif id in {c['id'] for c in meta}:action=f'<a class="btn btn-primary" href="/courses/{id}.html">Explore the written course</a>';description=x['description']
 else:action='<p class="cl-release-status">Resource release being prepared</p>';description=x['description']
 # This page provides an orientation and a first action, not the full paid workbook or an unrendered intro.
 artifact=x['artifact'];purpose=x['purpose'];firstaction=x['firstAction']
 body=f'''<header class="cl-hero"><div class="container"><a class="cl-back" href="/courses.html#workbooks">Workbook orientations</a><p class="cl-label">Start with your resource</p><h1>{h(title)}</h1><p class="lead">{h(description)}</p><p>This page helps you begin the resource. It is not a complete video course or a replacement for your workbook.</p><div class="cl-actions">{action}</div></div></header><div class="container cl-content"><section class="cl-section cl-two-column"><div><h2>Your first action</h2><p class="cl-first-action">{h(firstaction)}</p><p>Use a notebook, accessible text or your purchased resource. Keep your responses private and set a date to review your next step.</p></div><div><h2>What to work toward</h2><p>{h(purpose)}.</p><p>Your working evidence: {h(artifact)}.</p></div></section><section class="cl-section"><h2>Use it with care.</h2><p>{h(x['claimBoundary'])}</p><p>Resource-specific instructional videos are being prepared. The shared Brian AI avatar welcome below introduces The Ballers Kingdom and is not a demonstration of this workbook’s exercises.</p></section>{welcome()}<section class="cl-section"><h2>Keep learning.</h2><a class="btn btn-outline" href="/courses.html">Explore all learning paths</a></section></div>'''
 if id in data.get('resourceIntros',{}):
  body=body.replace(welcome(),specific_intro(data['resourceIntros'][id],title))
  body=body.replace('Resource-specific instructional videos are being prepared. The shared Brian AI avatar welcome below introduces The Ballers Kingdom and is not a demonstration of this workbook’s exercises.','A resource-specific Brian avatar introduction is available below. Use it alongside the original workbook and its practice exercises.')
 (SITE/'courses'/('resource-'+id+'.html')).write_text(page(title+' — Start here',description,body,path.lstrip('/')))
 orientations.append({'id':id,'title':title,'path':path,'firstAction':firstaction,'resourceUrl':p['resourceUrl'] if p else None})

body=f'''<header class="cl-hero"><div class="container cl-hub-hero"><div><p class="cl-label">Learning with Brian Kennedy Jr., M.Ed.</p><h1>Put your learning<br>to work.</h1><p class="lead">Make an educational decision. Build a useful relationship. Test an offer. Show what you can do.</p><p>Practical learning paths connect education, career, entrepreneurship, and the work of helping people grow.</p><div class="cl-actions"><a class="btn btn-primary" href="#learning-paths">Find your learning path</a><a class="btn btn-outline" href="#workbooks">Start with your workbook</a></div></div><div class="cl-hero-note"><p class="cl-big-quote">Learn it. <br>Try it. <br>Show the work.</p><p>Original written lessons, worked examples, exercises, and a final project. Explore each preview for current release details.</p><a href="#brian-welcome">Meet Brian through his AI avatar</a></div></div></header><div class="container cl-content"><section id="learning-paths" class="cl-section"><div class="cl-section-heading"><h2>Choose the work you want to do.</h2><p>Eight focused paths. Each connects a useful question to an artifact you can explain and improve.</p></div><div class="cl-course-grid">{''.join(card(c) for c in meta)}</div></section><section class="cl-section cl-format"><h2>A practical written edition.</h2><div class="cl-three-column"><div><h3>Understand</h3><p>Read clear teaching and a fictional worked example. Check the limits of the claim.</p></div><div><h3>Practice</h3><p>Use accessible templates with your own private situation or a supplied fictional case.</p></div><div><h3>Make it usable</h3><p>Complete a final project, assess it with an original rubric and return for a later transfer check.</p></div></div><p>Each learning path has a course-specific Brian avatar introduction. Course video updates pair narrated worked examples with the written lessons, practice and assessment; previews explain the current delivery. The shared welcome below introduces The Ballers Kingdom.</p></section><section id="brian-welcome">{welcome()}</section><section class="cl-section" id="workbooks"><div class="cl-section-heading"><h2>Already have a workbook?</h2><p>Open its orientation for a first action, transcript and the current Brian introduction.</p></div><div class="cl-resource-list">{''.join('<a href="'+h(o['path'])+'"><span>'+h(o['title'])+'</span><span aria-hidden="true">Open</span></a>' for o in orientations)}</div></section><section class="cl-section cl-next"><h2>Bring the learning to your group.</h2><p>Ask about students, returning learners, families, staff teams, or a facilitated entrepreneurship program. Delivery and institutional use are scoped separately.</p><a class="btn btn-outline" href="/contact.html">Discuss group learning</a></section></div>'''
(SITE/'courses.html').write_text(page('Courses & learning','Practical education, career, entrepreneurship and facilitation learning paths with Brian Kennedy Jr., M.Ed.',body,'courses.html'))

print(json.dumps({'hub':1,'coursePreviews':len(meta),'orientations':len(orientations),'publicMetadataOnly':True}))
